use xiom.io;
// Sortable: Types that can be ordered relative to each other.
// Implement this to enable sorting and comparison operations.
interface Sortable {
  // Returns true when self should come before other in sorted order.
  fn is_before(&self, other: &Self) -> Bool;
}

// The inventory module tracks stock levels for items.
// Pub API: add_item (increase stock), remove_item (decrease stock)
//          get_quantity (check current level)
module inventory {
  type Stock = { items: Vec[Str]; }

  pub fn add_item(s: &mut Stock, name: Str, qty: Int) { }
  pub fn remove_item(s: &mut Stock, name: Str) -> Bool { true }
  pub fn get_quantity(s: &Stock, name: Str) -> Int { 0 }
}

fn main() -> Int {
  return 0;
}
